export interface Todo {
  id: string;
  text: string;
  completed: boolean;
  createdAt: number;
}

export type TodoMap = Record<string, Todo[]>;

export interface EventDetails {
  title: string;
  date: string; // ISO string
}

export interface DateParts {
  year: number;
  month: number;
  day: number;
}

export enum ViewMode {
  CALENDAR = 'CALENDAR',
  SETTINGS = 'SETTINGS'
}

export const DAYS_IN_WEEK = 7;
export const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];
export const DAY_NAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

export const getDaysInMonth = (year: number, month: number): number => {
  return new Date(year, month + 1, 0).getDate();
};

export const getFirstDayOfMonth = (year: number, month: number): number => {
  return new Date(year, month, 1).getDay();
};

export const formatDateKey = (date: Date): string => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

export const isSameDay = (d1: Date, d2: Date): boolean => {
  return (
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate()
  );
};

export const isToday = (date: Date): boolean => {
  return isSameDay(date, new Date());
};

export const addMonths = (date: Date, amount: number): Date => {
  const newDate = new Date(date);
  newDate.setMonth(newDate.getMonth() + amount);
  return newDate;
};

export const getCalendarCells = (currentDate: Date) => {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  // Previous month padding
  const paddingDays = firstDay;
  const prevMonthDays = getDaysInMonth(year, month - 1);

  const cells = [];

  // Padding from prev month
  for (let i = paddingDays - 1; i >= 0; i--) {
    cells.push({
      date: new Date(year, month - 1, prevMonthDays - i),
      isCurrentMonth: false
    });
  }

  // Current month days
  for (let i = 1; i <= daysInMonth; i++) {
    cells.push({
      date: new Date(year, month, i),
      isCurrentMonth: true
    });
  }

  // Next month padding to fill row
  const remainingCells = 42 - cells.length; // 6 rows * 7 days
  for (let i = 1; i <= remainingCells; i++) {
    cells.push({
      date: new Date(year, month + 1, i),
      isCurrentMonth: false
    });
  }

  return cells;
};

export const getTimeRemaining = (targetDateStr: string) => {
  const total = Date.parse(targetDateStr) - Date.parse(new Date().toISOString());
  if (total <= 0) {
    return { total, days: 0, hours: 0, minutes: 0, seconds: 0 };
  }
  const seconds = Math.floor((total / 1000) % 60);
  const minutes = Math.floor((total / 1000 / 60) % 60);
  const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
  const days = Math.floor(total / (1000 * 60 * 60 * 24));

  return { total, days, hours, minutes, seconds };
};

import { useState, useEffect } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T): [T, (value: T | ((val: T) => T)) => void] {
  // Get from local storage then
  // parse stored json or if none return initialValue
  const readValue = (): T => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  };

  const [storedValue, setStoredValue] = useState<T>(readValue);

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  };

  useEffect(() => {
    setStoredValue(readValue());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return [storedValue, setValue];
}

import React, { useEffect, useState } from 'react';
import { getTimeRemaining } from '../utils/dateUtils';
import { EventDetails } from '../types';
import { Clock, Flag } from 'lucide-react';

interface CountdownProps {
  event: EventDetails;
  onEdit: () => void;
}

const Countdown: React.FC<CountdownProps> = ({ event, onEdit }) => {
  const [timeLeft, setTimeLeft] = useState(getTimeRemaining(event.date));

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(getTimeRemaining(event.date));
    }, 1000);

    return () => clearInterval(timer);
  }, [event.date]);

  const isExpired = timeLeft.total <= 0;

  return (
    <div className="relative overflow-hidden rounded-2xl bg-white dark:bg-slate-900 shadow-sm border border-slate-200 dark:border-slate-800 p-8 text-center mb-6">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>

      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-400 font-medium text-sm uppercase tracking-wider">
           <Flag size={16} />
           <span>Target Event</span>
        </div>
        <button 
          onClick={onEdit}
          className="text-slate-400 hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-300 transition-colors text-sm"
        >
          Edit Event
        </button>
      </div>

      <h2 className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white mb-8">
        {event.title || "Untitled Event"}
      </h2>

      {isExpired ? (
        <div className="flex flex-col items-center justify-center py-6 animate-fade-in">
          <Clock size={48} className="text-indigo-500 mb-4" />
          <p className="text-2xl font-semibold text-slate-700 dark:text-slate-300">The event has arrived!</p>
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-3xl mx-auto">
          <TimeBlock value={timeLeft.days} label="Days" />
          <TimeBlock value={timeLeft.hours} label="Hours" />
          <TimeBlock value={timeLeft.minutes} label="Minutes" />
          <TimeBlock value={timeLeft.seconds} label="Seconds" />
        </div>
      )}

      <div className="mt-8 text-sm text-slate-500 dark:text-slate-400">
        Target Date: {new Date(event.date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
      </div>
    </div>
  );
};

const TimeBlock = ({ value, label }: { value: number; label: string }) => (
  <div className="flex flex-col items-center p-4 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800/50">
    <span className="text-4xl md:text-5xl font-bold text-indigo-600 dark:text-indigo-400 font-mono">
      {String(value).padStart(2, '0')}
    </span>
    <span className="text-xs md:text-sm text-slate-500 dark:text-slate-400 uppercase tracking-widest mt-2">
      {label}
    </span>
  </div>
);

export default Countdown;

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { 
  getCalendarCells, 
  MONTH_NAMES, 
  DAY_NAMES, 
  addMonths, 
  formatDateKey, 
  isSameDay, 
  isToday 
} from '../utils/dateUtils';
import { TodoMap } from '../types';

interface CalendarProps {
  selectedDate: Date;
  onSelectDate: (date: Date) => void;
  todos: TodoMap;
  targetDateStr: string;
}

const Calendar: React.FC<CalendarProps> = ({ selectedDate, onSelectDate, todos, targetDateStr }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const cells = getCalendarCells(currentMonth);
  const targetDate = new Date(targetDateStr);

  const handlePrevMonth = () => setCurrentMonth(addMonths(currentMonth, -1));
  const handleNextMonth = () => setCurrentMonth(addMonths(currentMonth, 1));
  const handleToday = () => {
    const now = new Date();
    setCurrentMonth(now);
    onSelectDate(now);
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden h-full flex flex-col">
      {/* Header */}
      <div className="p-4 md:p-6 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <h3 className="text-xl font-semibold text-slate-800 dark:text-slate-100">
          {MONTH_NAMES[currentMonth.getMonth()]} {currentMonth.getFullYear()}
        </h3>
        <div className="flex items-center gap-2">
          <button 
            onClick={handleToday}
            className="text-xs font-medium px-3 py-1.5 rounded-md bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition-colors mr-2"
          >
            Today
          </button>
          <button 
            onClick={handlePrevMonth}
            className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
          >
            <ChevronLeft size={20} />
          </button>
          <button 
            onClick={handleNextMonth}
            className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
          >
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      {/* Grid Header */}
      <div className="grid grid-cols-7 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        {DAY_NAMES.map(day => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-400 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Grid Body */}
      <div className="grid grid-cols-7 auto-rows-fr flex-grow p-2 gap-2">
        {cells.map((cell, index) => {
          const dateKey = formatDateKey(cell.date);
          const dayTodos = todos[dateKey] || [];
          const incompleteCount = dayTodos.filter(t => !t.completed).length;
          const isSelected = isSameDay(cell.date, selectedDate);
          const isCurrentDay = isToday(cell.date);
          const isTargetDay = isSameDay(cell.date, targetDate);

          return (
            <button
              key={index}
              onClick={() => onSelectDate(cell.date)}
              className={`
                relative flex flex-col items-center justify-start pt-2 rounded-xl transition-all duration-200 min-h-[80px] md:min-h-[100px]
                ${!cell.isCurrentMonth ? 'opacity-30' : 'opacity-100'}
                ${isSelected 
                  ? 'bg-indigo-50 dark:bg-indigo-900/20 ring-2 ring-indigo-500 ring-inset z-10' 
                  : 'hover:bg-slate-50 dark:hover:bg-slate-800/50'}
                ${isTargetDay ? 'bg-amber-50 dark:bg-amber-900/10' : ''}
              `}
            >
              <div className={`
                w-8 h-8 flex items-center justify-center rounded-full text-sm font-medium mb-1
                ${isCurrentDay 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200 dark:shadow-none' 
                  : isTargetDay
                    ? 'bg-amber-500 text-white shadow-md shadow-amber-200 dark:shadow-none'
                    : 'text-slate-700 dark:text-slate-300'}
              `}>
                {cell.date.getDate()}
              </div>

              {/* Indicators */}
              <div className="flex gap-1 mt-1">
                 {dayTodos.length > 0 && (
                   <div className="flex flex-col items-center gap-0.5">
                     {incompleteCount > 0 && (
                       <span className="w-1.5 h-1.5 rounded-full bg-rose-500"></span>
                     )}
                     {dayTodos.length > incompleteCount && (
                       <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                     )}
                   </div>
                 )}
              </div>

              {isTargetDay && cell.isCurrentMonth && (
                 <span className="text-[10px] font-bold text-amber-600 dark:text-amber-500 mt-1 uppercase tracking-tight px-1 truncate w-full text-center">
                   Event
                 </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState } from 'react';
import { Plus, Trash2, CheckCircle, Circle, Calendar as CalendarIcon, X } from 'lucide-react';
import { Todo } from '../types';
import { formatDateKey } from '../utils/dateUtils';

interface TodoListProps {
  date: Date;
  todos: Todo[];
  onAddTodo: (text: string) => void;
  onToggleTodo: (id: string) => void;
  onDeleteTodo: (id: string) => void;
}

const TodoList: React.FC<TodoListProps> = ({ date, todos, onAddTodo, onToggleTodo, onDeleteTodo }) => {
  const [inputValue, setInputValue] = useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputValue.trim()) {
      onAddTodo(inputValue.trim());
      setInputValue("");
    }
  };

  const formattedDate = date.toLocaleDateString(undefined, {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  const sortedTodos = [...todos].sort((a, b) => {
    if (a.completed === b.completed) return b.createdAt - a.createdAt;
    return a.completed ? 1 : -1;
  });

  const completionPercentage = todos.length > 0 
    ? Math.round((todos.filter(t => t.completed).length / todos.length) * 100)
    : 0;

  return (
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 h-full flex flex-col">
      <div className="p-6 border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-start gap-3 mb-1">
          <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg text-indigo-600 dark:text-indigo-400">
            <CalendarIcon size={20} />
          </div>
          <div>
            <h3 className="font-semibold text-slate-900 dark:text-white text-lg leading-tight">
              {formattedDate}
            </h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm">
              {todos.length} tasks · {completionPercentage}% done
            </p>
          </div>
        </div>

        {/* Progress Bar */}
        <div className="mt-4 h-1.5 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
          <div 
            className="h-full bg-indigo-500 transition-all duration-500 ease-out"
            style={{ width: `${completionPercentage}%` }}
          />
        </div>
      </div>

      <div className="flex-grow overflow-y-auto p-4 space-y-2">
        {todos.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-600 p-8 text-center">
            <div className="w-16 h-16 rounded-full bg-slate-50 dark:bg-slate-800 flex items-center justify-center mb-3">
              <CheckCircle size={24} className="opacity-50" />
            </div>
            <p>No tasks for this day.</p>
            <p className="text-sm">Add one below to get started.</p>
          </div>
        ) : (
          sortedTodos.map(todo => (
            <div 
              key={todo.id} 
              className={`
                group flex items-center gap-3 p-3 rounded-xl border transition-all duration-200
                ${todo.completed 
                  ? 'bg-slate-50 dark:bg-slate-900/50 border-transparent opacity-75' 
                  : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-indigo-200 dark:hover:border-indigo-900'}
              `}
            >
              <button 
                onClick={() => onToggleTodo(todo.id)}
                className={`flex-shrink-0 transition-colors ${todo.completed ? 'text-emerald-500' : 'text-slate-300 hover:text-indigo-500'}`}
              >
                {todo.completed ? <CheckCircle size={22} className="fill-emerald-50 dark:fill-emerald-900/20" /> : <Circle size={22} />}
              </button>

              <span className={`flex-grow text-sm ${todo.completed ? 'text-slate-400 line-through' : 'text-slate-700 dark:text-slate-200'}`}>
                {todo.text}
              </span>

              <button 
                onClick={() => onDeleteTodo(todo.id)}
                className="opacity-0 group-hover:opacity-100 p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-all"
              >
                <Trash2 size={16} />
              </button>
            </div>
          ))
        )}
      </div>

      <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 rounded-b-2xl">
        <form onSubmit={handleSubmit} className="flex gap-2">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="Add a new task..."
            className="flex-grow px-4 py-2.5 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 transition-all text-sm dark:text-white"
          />
          <button 
            type="submit"
            disabled={!inputValue.trim()}
            className="p-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            <Plus size={20} />
          </button>
        </form>
      </div>
    </div>
  );
};

export default TodoList;

import React, { useState } from 'react';
import { X, Calendar, Type } from 'lucide-react';
import { EventDetails } from '../types';

interface EventSettingsProps {
  currentEvent: EventDetails;
  onSave: (event: EventDetails) => void;
  onClose: () => void;
}

const EventSettings: React.FC<EventSettingsProps> = ({ currentEvent, onSave, onClose }) => {
  const [title, setTitle] = useState(currentEvent.title);
  // Extract date part only (YYYY-MM-DD) for input
  const [date, setDate] = useState(currentEvent.date.split('T')[0]);
  const [time, setTime] = useState(currentEvent.date.includes('T') ? currentEvent.date.split('T')[1].substring(0, 5) : "00:00");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateTime = `${date}T${time}:00`;
    onSave({ title, date: dateTime });
