import React, { useState, useEffect } from 'react';
import { Moon, Sun, Layout, CheckSquare } from 'lucide-react';
import { useLocalStorage } from './hooks/useLocalStorage';
import { TodoMap, EventDetails, Todo } from './types';
import { formatDateKey } from './utils/dateUtils';
import Calendar from './components/Calendar';
import TodoList from './components/TodoList';
import Countdown from './components/Countdown';
import EventSettings from './components/EventSettings';

const DEFAULT_EVENT: EventDetails = {
  title: "New Year's Day",
  date: `${new Date().getFullYear() + 1}-01-01T00:00:00`
};

const App: React.FC = () => {
  // Theme State
  const [darkMode, setDarkMode] = useLocalStorage<boolean>('theme-dark', false);

  // Data State
  const [event, setEvent] = useLocalStorage<EventDetails>('target-event', DEFAULT_EVENT);
  const [todos, setTodos] = useLocalStorage<TodoMap>('todos-map', {});

  // UI State
  // Persist selected date to maintain session view
  const [selectedDateStr, setSelectedDateStr] = useLocalStorage<string>('selected-date', new Date().toISOString());

  // Parse date safely
  let selectedDate = new Date(selectedDateStr);
  if (isNaN(selectedDate.getTime())) {
    selectedDate = new Date();
  }

  const [showSettings, setShowSettings] = useState(false);

  // Apply dark mode class
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const toggleTheme = () => setDarkMode(prev => !prev);

  // Date Selection Handler
  const handleSelectDate = (date: Date) => {
    setSelectedDateStr(date.toISOString());
  };

  // Todo Handlers
  const handleAddTodo = (text: string) => {
    const key = formatDateKey(selectedDate);
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text,
      completed: false,
      createdAt: Date.now()
    };

    setTodos(prev => ({
      ...prev,
      [key]: [...(prev[key] || []), newTodo]
    }));
  };

  const handleToggleTodo = (id: string) => {
    const key = formatDateKey(selectedDate);
    if (!todos[key]) return;

    setTodos(prev => ({
      ...prev,
      [key]: prev[key].map(t => t.id === id ? { ...t, completed: !t.completed } : t)
    }));
  };

  const handleDeleteTodo = (id: string) => {
    const key = formatDateKey(selectedDate);
    if (!todos[key]) return;

    setTodos(prev => ({
      ...prev,
      [key]: prev[key].filter(t => t.id !== id)
    }));
  };

  const handleSaveEvent = (newEvent: EventDetails) => {
    setEvent(newEvent);
    setShowSettings(false);
  };

  const selectedKey = formatDateKey(selectedDate);
  const currentTodos = todos[selectedKey] || [];

  return (
    <div className="min-h-screen pb-12 transition-colors duration-300">
      {/* Navigation / Header */}
      <nav className="sticky top-0 z-40 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
                <Layout size={20} />
              </div>
              <span className="font-bold text-xl text-slate-900 dark:text-white tracking-tight">
                Event<span className="text-indigo-600 dark:text-indigo-400">Horizon</span>
              </span>
            </div>

            <button 
              onClick={toggleTheme}
              className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400 transition-all"
              aria-label="Toggle Theme"
            >
              {darkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Hero Section: Countdown */}
        <section className="animate-fade-in-down">
          <Countdown 
            event={event} 
            onEdit={() => setShowSettings(true)} 
          />
        </section>

        {/* Dashboard Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:h-[600px]">

          {/* Calendar Section (Takes 2 columns) */}
          <div className="lg:col-span-2 h-full min-h-[500px]">
             <Calendar 
               selectedDate={selectedDate}
               onSelectDate={handleSelectDate}
               todos={todos}
               targetDateStr={event.date}
             />
          </div>

          {/* Daily Tasks Section (Takes 1 column) */}
          <div className="lg:col-span-1 h-full min-h-[500px]">
             <TodoList 
               date={selectedDate}
               todos={currentTodos}
               onAddTodo={handleAddTodo}
               onToggleTodo={handleToggleTodo}
               onDeleteTodo={handleDeleteTodo}
             />
          </div>

        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <EventSettings 
          currentEvent={event}
          onSave={handleSaveEvent}
          onClose={() => setShowSettings(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { 
  getCalendarCells, 
  MONTH_NAMES, 
  DAY_NAMES, 
  addMonths, 
  formatDateKey, 
  isSameDay, 
  isToday 
} from '../utils/dateUtils';
import { TodoMap } from '../types';

interface CalendarProps {
  selectedDate: Date;
  onSelectDate: (date: Date) => void;
  todos: TodoMap;
  targetDateStr: string;
}

const Calendar: React.FC<CalendarProps> = ({ selectedDate, onSelectDate, todos, targetDateStr }) => {
  // Initialize currentMonth to the selectedDate so the view opens on the correct month
  const [currentMonth, setCurrentMonth] = useState(selectedDate);

  const cells = getCalendarCells(currentMonth);
  const targetDate = new Date(targetDateStr);

  const handlePrevMonth = () => setCurrentMonth(addMonths(currentMonth, -1));
  const handleNextMonth = () => setCurrentMonth(addMonths(currentMonth, 1));
  const handleToday = () => {
    const now = new Date();
    setCurrentMonth(now);
    onSelectDate(now);
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden h-full flex flex-col">
      {/* Header */}
      <div className="p-4 md:p-6 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <h3 className="text-xl font-semibold text-slate-800 dark:text-slate-100">
          {MONTH_NAMES[currentMonth.getMonth()]} {currentMonth.getFullYear()}
        </h3>
        <div className="flex items-center gap-2">
          <button 
            onClick={handleToday}
            className="text-xs font-medium px-3 py-1.5 rounded-md bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition-colors mr-2"
          >
            Today
          </button>
          <button 
            onClick={handlePrevMonth}
            className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
          >
            <ChevronLeft size={20} />
          </button>
          <button 
            onClick={handleNextMonth}
            className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full text-slate-500 dark:text-slate-400 transition-colors"
          >
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      {/* Grid Header */}
      <div className="grid grid-cols-7 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        {DAY_NAMES.map(day => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-400 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Grid Body */}
      <div className="grid grid-cols-7 auto-rows-fr flex-grow p-2 gap-2">
        {cells.map((cell, index) => {
          const dateKey = formatDateKey(cell.date);
          const dayTodos = todos[dateKey] || [];
          const incompleteCount = dayTodos.filter(t => !t.completed).length;
          const isSelected = isSameDay(cell.date, selectedDate);
          const isCurrentDay = isToday(cell.date);
          const isTargetDay = isSameDay(cell.date, targetDate);

          return (
            <button
              key={index}
              onClick={() => onSelectDate(cell.date)}
              className={`
                relative flex flex-col items-center justify-start pt-2 rounded-xl transition-all duration-200 min-h-[80px] md:min-h-[100px]
                ${!cell.isCurrentMonth ? 'opacity-30' : 'opacity-100'}
                ${isSelected 
                  ? 'bg-indigo-50 dark:bg-indigo-900/20 ring-2 ring-indigo-500 ring-inset z-10' 
                  : 'hover:bg-slate-50 dark:hover:bg-slate-800/50'}
                ${isTargetDay ? 'bg-amber-50 dark:bg-amber-900/10' : ''}
              `}
            >
              <div className={`
                w-8 h-8 flex items-center justify-center rounded-full text-sm font-medium mb-1
                ${isCurrentDay 
                  ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200 dark:shadow-none' 
                  : isTargetDay
                    ? 'bg-amber-500 text-white shadow-md shadow-amber-200 dark:shadow-none'
                    : 'text-slate-700 dark:text-slate-300'}
              `}>
                {cell.date.getDate()}
              </div>

              {/* Indicators */}
              <div className="flex gap-1 mt-1">
                 {dayTodos.length > 0 && (
                   <div className="flex flex-col items-center gap-0.5">
                     {incompleteCount > 0 && (
                       <span className="w-1.5 h-1.5 rounded-full bg-rose-500"></span>
                     )}
                     {dayTodos.length > incompleteCount && (
                       <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                     )}
                   </div>
                 )}
              </div>

              {isTargetDay && cell.isCurrentMonth && (
                 <span className="text-[10px] font-bold text-amber-600 dark:text-amber-500 mt-1 uppercase tracking-tight px-1 truncate w-full text-center">
                   Event
                 </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default Calendar;

