import React, { useState, useEffect } from 'react';
import { Moon, Sun, Layout, LogOut, Loader2, AlertTriangle, WifiOff } from 'lucide-react';
import firebase from 'firebase/app';
import { auth, db, isFirebaseConfigured } from './lib/firebase';

import { useLocalStorage } from './hooks/useLocalStorage';
import { TodoMap, EventDetails, Todo } from './types';
import { formatDateKey } from './utils/dateUtils';
import Calendar from './components/Calendar';
import TodoList from './components/TodoList';
import Countdown from './components/Countdown';
import EventSettings from './components/EventSettings';
import Login from './components/Login';

const DEFAULT_EVENT: EventDetails = {
  title: "New Year's Day",
  date: `${new Date().getFullYear() + 1}-01-01T00:00:00`
};

const App: React.FC = () => {
  // Theme State (Local Only)
  const [darkMode, setDarkMode] = useLocalStorage<boolean>('theme-dark', false);

  // Auth State
  const [user, setUser] = useState<firebase.User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  // Data State (From Firebase)
  const [event, setEvent] = useState<EventDetails>(DEFAULT_EVENT);
  const [todos, setTodos] = useState<TodoMap>({});

  // UI State
  const [selectedDateStr, setSelectedDateStr] = useLocalStorage<string>('selected-date', new Date().toISOString());
  const [showSettings, setShowSettings] = useState(false);

  // Parse selected date
  let selectedDate = new Date(selectedDateStr);
  if (isNaN(selectedDate.getTime())) {
    selectedDate = new Date();
  }

  // 1. Initialize Auth Listener
  useEffect(() => {
    if (!isFirebaseConfigured() || !auth) {
      setAuthLoading(false);
      return;
    }

    const unsubscribe = auth.onAuthStateChanged((currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });

    return unsubscribe;
  }, []);

  // 2. Subscribe to Data (When user is logged in)
  useEffect(() => {
    if (!user || !db) return;

    setDbError(null);

    // A. Subscribe to Event Settings
    const eventRef = db.collection('users').doc(user.uid).collection('settings').doc('targetEvent');
    const unsubEvent = eventRef.onSnapshot(
      (docSnap) => {
        if (docSnap.exists) {
          setEvent(docSnap.data() as EventDetails);
        } else {
          // Initialize if doesn't exist
          eventRef.set(DEFAULT_EVENT).catch(err => {
             console.error("Error creating init doc:", err);
             setDbError("Insufficient permissions to create data. Check Firestore Rules.");
          });
        }
      },
      (error) => {
        console.error("Event subscription error:", error);
        setDbError("Database access denied. Please ensure your Firestore Database is created and Rules allow read/write.");
      }
    );

    // B. Subscribe to Todos
    const todosRef = db.collection('users').doc(user.uid).collection('todos');
    const unsubTodos = todosRef.onSnapshot(
      (snapshot) => {
        const newTodoMap: TodoMap = {};
        snapshot.forEach((doc) => {
          const data = doc.data();
          if (data.list && Array.isArray(data.list)) {
            newTodoMap[doc.id] = data.list;
          }
        });
        setTodos(newTodoMap);
      },
      (error) => {
        console.error("Todos subscription error:", error);
      }
    );

    return () => {
      unsubEvent();
      unsubTodos();
    };
  }, [user]);

  // Apply dark mode
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const toggleTheme = () => setDarkMode(prev => !prev);
  const handleSelectDate = (date: Date) => setSelectedDateStr(date.toISOString());

  // --- Handlers (Firestore Ops) ---

  const handleSaveEvent = async (newEvent: EventDetails) => {
    if (!user || !db) return;
    setEvent(newEvent); // Optimistic update
    setShowSettings(false);
    try {
      await db.collection('users').doc(user.uid).collection('settings').doc('targetEvent').set(newEvent);
    } catch (e) {
      console.error("Error saving event:", e);
      setDbError("Failed to save. Check internet or permissions.");
    }
  };

  const handleAddTodo = async (text: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text,
      completed: false,
      createdAt: Date.now()
    };

    const currentList = todos[key] || [];
    const newList = [...currentList, newTodo];

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    try {
      await db.collection('users').doc(user.uid).collection('todos').doc(key).set({ list: newList });
    } catch (e) {
      console.error("Error adding todo:", e);
    }
  };

  const handleToggleTodo = async (id: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const currentList = todos[key];
    if (!currentList) return;

    const newList = currentList.map(t => t.id === id ? { ...t, completed: !t.completed } : t);

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    await db.collection('users').doc(user.uid).collection('todos').doc(key).set({ list: newList });
  };

  const handleDeleteTodo = async (id: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const currentList = todos[key];
    if (!currentList) return;

    const newList = currentList.filter(t => t.id !== id);

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    await db.collection('users').doc(user.uid).collection('todos').doc(key).set({ list: newList });
  };

  const handleSignOut = () => {
    if (auth) auth.signOut();
  };

  // --- Render Logic ---

  if (!isFirebaseConfigured()) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 p-4">
        <div className="max-w-lg w-full bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-rose-200 dark:border-rose-900 p-8 text-center">
          <div className="flex justify-center mb-4 text-rose-500">
            <AlertTriangle size={48} />
          </div>
          <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Setup Required</h2>
          <p className="text-slate-600 dark:text-slate-400 mb-6">
            To enable cloud syncing, you need to add your Firebase configuration.
          </p>
          <div className="bg-slate-100 dark:bg-slate-950 p-4 rounded-lg text-left text-sm font-mono text-slate-700 dark:text-slate-300 overflow-x-auto mb-6 border border-slate-200 dark:border-slate-800">
            open lib/firebase.ts<br/>
            paste your firebaseConfig
          </div>
          <p className="text-xs text-slate-400">
            Refresh this page after saving the file.
          </p>
        </div>
      </div>
    );
  }

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <Loader2 className="animate-spin text-indigo-600" size={32} />
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const selectedKey = formatDateKey(selectedDate);
  const currentTodos = todos[selectedKey] || [];

  return (
    <div className="min-h-screen pb-12 transition-colors duration-300">
      {/* Navigation / Header */}
      <nav className="sticky top-0 z-40 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
                <Layout size={20} />
              </div>
              <span className="font-bold text-xl text-slate-900 dark:text-white tracking-tight">
                Event<span className="text-indigo-600 dark:text-indigo-400">Horizon</span>
              </span>
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={toggleTheme}
                className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400 transition-all"
                title="Toggle Theme"
              >
                {darkMode ? <Sun size={20} /> : <Moon size={20} />}
              </button>
              <div className="h-6 w-px bg-slate-200 dark:bg-slate-800 mx-1"></div>
              <button 
                onClick={handleSignOut}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-900/20 text-slate-600 dark:text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 transition-all text-sm font-medium"
                title="Sign Out"
              >
                <LogOut size={16} />
                <span className="hidden sm:inline">Sign Out</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Error Banner */}
        {dbError && (
          <div className="mb-6 p-4 bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl flex items-center gap-3 text-rose-700 dark:text-rose-300 animate-fade-in">
            <WifiOff size={24} />
            <div className="flex-grow font-medium">{dbError}</div>
          </div>
        )}

        {/* Hero Section: Countdown */}
        <section className="animate-fade-in-down">
          <Countdown 
            event={event} 
            onEdit={() => setShowSettings(true)} 
          />
        </section>

        {/* Dashboard Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:h-[600px]">

          {/* Calendar Section (Takes 2 columns) */}
          <div className="lg:col-span-2 h-full min-h-[500px]">
             <Calendar 
               selectedDate={selectedDate}
               onSelectDate={handleSelectDate}
               todos={todos}
               targetDateStr={event.date}
             />
          </div>

          {/* Daily Tasks Section (Takes 1 column) */}
          <div className="lg:col-span-1 h-full min-h-[500px]">
             <TodoList 
               date={selectedDate}
               todos={currentTodos}
               onAddTodo={handleAddTodo}
               onToggleTodo={handleToggleTodo}
               onDeleteTodo={handleDeleteTodo}
             />
          </div>

        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <EventSettings 
          currentEvent={event}
          onSave={handleSaveEvent}
          onClose={() => setShowSettings(false)}
        />
      )}
    </div>
  );
};

export default App;

