    if (!isFirebaseConfigured() || !auth) {
      setAuthLoading(false);
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });

    return unsubscribe;
  }, []);

  // 2. Subscribe to Data (When user is logged in)
  useEffect(() => {
    if (!user || !db) return;

    setDbError(null);

    // A. Subscribe to Event Settings
    const eventRef = doc(db, 'users', user.uid, 'settings', 'targetEvent');
    const unsubEvent = onSnapshot(eventRef, 
      (docSnap) => {
        if (docSnap.exists()) {
          setEvent(docSnap.data() as EventDetails);
        } else {
          // Initialize if doesn't exist
          setDoc(eventRef, DEFAULT_EVENT).catch(err => {
             console.error("Error creating init doc:", err);
             setDbError("Insufficient permissions to create data. Check Firestore Rules.");
          });
        }
      },
      (error) => {
        console.error("Event subscription error:", error);
        setDbError("Database access denied. Please ensure your Firestore Database is created and Rules allow read/write.");
      }
    );

    // B. Subscribe to Todos
    const todosRef = collection(db, 'users', user.uid, 'todos');
    const unsubTodos = onSnapshot(todosRef, 
      (snapshot) => {
        const newTodoMap: TodoMap = {};
        snapshot.forEach((doc) => {
          const data = doc.data();
          if (data.list && Array.isArray(data.list)) {
            newTodoMap[doc.id] = data.list;
          }
        });
        setTodos(newTodoMap);
      },
      (error) => {
        console.error("Todos subscription error:", error);
      }
    );

    return () => {
      unsubEvent();
      unsubTodos();
    };
  }, [user]);

  // Apply dark mode
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const toggleTheme = () => setDarkMode(prev => !prev);
  const handleSelectDate = (date: Date) => setSelectedDateStr(date.toISOString());

  // --- Handlers (Firestore Ops) ---

  const handleSaveEvent = async (newEvent: EventDetails) => {
    if (!user || !db) return;
    setEvent(newEvent); // Optimistic update
    setShowSettings(false);
    try {
      await setDoc(doc(db, 'users', user.uid, 'settings', 'targetEvent'), newEvent);
    } catch (e) {
      console.error("Error saving event:", e);
      setDbError("Failed to save. Check internet or permissions.");
    }
  };

  const handleAddTodo = async (text: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text,
      completed: false,
      createdAt: Date.now()
    };

    const currentList = todos[key] || [];
    const newList = [...currentList, newTodo];

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    try {
      await setDoc(doc(db, 'users', user.uid, 'todos', key), { list: newList });
    } catch (e) {
      console.error("Error adding todo:", e);
    }
  };

  const handleToggleTodo = async (id: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const currentList = todos[key];
    if (!currentList) return;

    const newList = currentList.map(t => t.id === id ? { ...t, completed: !t.completed } : t);

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    await setDoc(doc(db, 'users', user.uid, 'todos', key), { list: newList });
  };

  const handleDeleteTodo = async (id: string) => {
    if (!user || !db) return;
    const key = formatDateKey(selectedDate);
    const currentList = todos[key];
    if (!currentList) return;

    const newList = currentList.filter(t => t.id !== id);

    // Optimistic Update
    setTodos(prev => ({ ...prev, [key]: newList }));

    // Firebase Update
    await setDoc(doc(db, 'users', user.uid, 'todos', key), { list: newList });
  };

  const handleSignOut = () => {
    if (auth) signOut(auth);
  };

  // --- Render Logic ---

  if (!isFirebaseConfigured()) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 p-4">
        <div className="max-w-lg w-full bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-rose-200 dark:border-rose-900 p-8 text-center">
          <div className="flex justify-center mb-4 text-rose-500">
            <AlertTriangle size={48} />
          </div>
          <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Setup Required</h2>
          <p className="text-slate-600 dark:text-slate-400 mb-6">
            To enable cloud syncing, you need to add your Firebase configuration.
          </p>
          <div className="bg-slate-100 dark:bg-slate-950 p-4 rounded-lg text-left text-sm font-mono text-slate-700 dark:text-slate-300 overflow-x-auto mb-6 border border-slate-200 dark:border-slate-800">
            open lib/firebase.ts<br/>
            paste your firebaseConfig
          </div>
          <p className="text-xs text-slate-400">
            Refresh this page after saving the file.
          </p>
        </div>
      </div>
    );
  }

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <Loader2 className="animate-spin text-indigo-600" size={32} />
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const selectedKey = formatDateKey(selectedDate);
  const currentTodos = todos[selectedKey] || [];

  return (
    <div className="min-h-screen pb-12 transition-colors duration-300">
      {/* Navigation / Header */}
      <nav className="sticky top-0 z-40 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800">
