        <div className="flex justify-center mb-6">
          <div className="bg-indigo-600 p-3 rounded-xl text-white shadow-lg shadow-indigo-200 dark:shadow-none">
            <Layout size={32} />
          </div>
        </div>

        <h1 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
          Welcome to Event Horizon
        </h1>
        <p className="text-slate-500 dark:text-slate-400 mb-8">
          Sign in to sync your events and tasks across all your devices.
        </p>

        <button
          onClick={handleGoogleLogin}
          disabled={isRedirecting}
          className="w-full flex items-center justify-center gap-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-medium py-3 px-4 rounded-xl transition-all duration-200 group disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isRedirecting ? (
             <Loader2 size={20} className="animate-spin text-indigo-600" />
          ) : (
            <>
              <img src="https://www.google.com/favicon.ico" alt="Google" className="w-5 h-5" />
              <span>Sign in with Google</span>
              <ArrowRight size={16} className="text-slate-400 group-hover:translate-x-1 transition-transform" />
            </>
          )}
        </button>

        {error && (
          <div className={`mt-6 p-3 text-sm rounded-lg text-left flex items-start gap-2 ${isDomainError ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300' : 'bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400'}`}>
            <AlertCircle size={18} className="flex-shrink-0 mt-0.5" />
            <div>
              <span className="font-bold block mb-1">
                {isDomainError ? "Redirecting..." : "Error"}
              </span>
              {error}
            </div>
          </div>
        )}

        <div className="relative my-6">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-slate-200 dark:border-slate-700"></div>
          </div>
          <div className="relative flex justify-center text-xs uppercase">
            <span className="bg-white dark:bg-slate-900 px-2 text-slate-400">Or continue locally</span>
          </div>
        </div>

        <button
          onClick={onGuestLogin}
          disabled={isRedirecting}
          className={`
            w-full flex items-center justify-center gap-3 font-medium py-3 px-4 rounded-xl transition-all duration-200
            bg-indigo-50 dark:bg-slate-800 border border-indigo-100 dark:border-slate-700 hover:bg-indigo-100 dark:hover:bg-slate-700 text-indigo-700 dark:text-slate-300 disabled:opacity-50
          `}
        >
          <User size={20} className="text-indigo-600 dark:text-slate-400" />
          <span>Continue as Guest</span>
        </button>

        <div className="mt-8 text-xs text-slate-400 dark:text-slate-500">
          Guest data is stored in your browser's local storage.
        </div>
      </div>
    </div>
  );
};

