import React, { useState, useEffect } from 'react';
import { Moon, Sun, LogOut, WifiOff } from 'lucide-react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { collection, onSnapshot, doc, setDoc, updateDoc, deleteDoc, query } from 'firebase/firestore';
import { auth, db } from './lib/firebase';
import Login from './components/Login';
import Countdown from './components/Countdown';
import Calendar from './components/Calendar';
import TodoList from './components/TodoList';
import EventSettings from './components/EventSettings';
import { Todo, TodoMap, EventDetails } from './types';
import { formatDateKey } from './utils/dateUtils';

const DEFAULT_EVENT: EventDetails = {
  title: "Set a Target Event",
  date: new Date(new Date().getFullYear(), 11, 31).toISOString()
};

export default function App() {
  const [user, setUser] = useState<any>(null);
  const [isGuest, setIsGuest] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());

  // Data State
  const [event, setEvent] = useState<EventDetails>(DEFAULT_EVENT);
  const [todos, setTodos] = useState<TodoMap>({});

  // UI State
  const [showSettings, setShowSettings] = useState(false);
  const [loading, setLoading] = useState(true);

  // Initialize Theme
  useEffect(() => {
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setDarkMode(true);
    }
  }, []);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  // Auth Listener
  useEffect(() => {
    if (!auth) {
      setLoading(false);
      return;
    }
    const unsubscribe = onAuthStateChanged(auth, (u: any) => {
      setUser(u);
      if (u) setIsGuest(false);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Guest Data Sync (Local Storage)
  useEffect(() => {
    if (isGuest) {
      try {
        const storedEvent = localStorage.getItem('guest_event');
        if (storedEvent) setEvent(JSON.parse(storedEvent));

        const storedTodos = localStorage.getItem('guest_todos');
        if (storedTodos) setTodos(JSON.parse(storedTodos));
      } catch (e) {
        console.error("Failed to load guest data", e);
      }
      setLoading(false);
    }
  }, [isGuest]);

  // Firebase Data Sync
  useEffect(() => {
    if (!user || !db || isGuest) return;

    // 1. Sync Event Settings
    const eventRef = doc(db, 'users', user.uid, 'settings', 'event');
    const unsubEvent = onSnapshot(eventRef, (docSnap: any) => {
      if (docSnap.exists()) {
        setEvent(docSnap.data() as EventDetails);
      } else {
        setDoc(eventRef, DEFAULT_EVENT);
      }
    });

    // 2. Sync Todos
    const todosRef = collection(db, 'users', user.uid, 'todos');
    const q = query(todosRef);
    const unsubTodos = onSnapshot(q, (snapshot: any) => {
      const newTodos: TodoMap = {};
      snapshot.forEach((doc: any) => {
        const data = doc.data();
        const key = data.dateKey;
        if (!newTodos[key]) newTodos[key] = [];
        newTodos[key].push({ id: doc.id, ...data } as Todo);
      });
      setTodos(newTodos);
    });

    return () => {
      unsubEvent();
      unsubTodos();
    };
  }, [user, isGuest]);

  // Handlers
  const handleSignOut = () => {
    if (user && auth) signOut(auth);
    setUser(null);
    setIsGuest(false);
    setEvent(DEFAULT_EVENT);
    setTodos({});
  };

  const handleUpdateEvent = async (newEvent: EventDetails) => {
    setEvent(newEvent);
    setShowSettings(false);

    if (user && db) {
      await setDoc(doc(db, 'users', user.uid, 'settings', 'event'), newEvent);
    } else if (isGuest) {
      localStorage.setItem('guest_event', JSON.stringify(newEvent));
    }
  };

  const handleAddTodo = async (text: string) => {
    const dateKey = formatDateKey(selectedDate);
    // Generate ID locally for optimistic/guest updates
    const tempId = Date.now().toString(); 

    if (user && db) {
      const newTodoRef = doc(collection(db, 'users', user.uid, 'todos'));
      await setDoc(newTodoRef, {
        text,
        completed: false,
        createdAt: Date.now(),
        dateKey
      });
    } else if (isGuest) {
      const newTodo: Todo = {
        id: tempId,
        text,
        completed: false,
        createdAt: Date.now()
      };

      const updatedTodos = { ...todos };
      if (!updatedTodos[dateKey]) updatedTodos[dateKey] = [];
      updatedTodos[dateKey].push(newTodo);

      setTodos(updatedTodos);
      localStorage.setItem('guest_todos', JSON.stringify(updatedTodos));
    }
  };

  const handleToggleTodo = async (id: string) => {
    if (user && db) {
      let targetTodo: Todo | undefined;
      for (const key in todos) {
        const found = todos[key].find(t => t.id === id);
        if (found) {
          targetTodo = found;
          break;
        }
      }

      if (targetTodo) {
        await updateDoc(doc(db, 'users', user.uid, 'todos', id), {
          completed: !targetTodo.completed
        });
      }
    } else if (isGuest) {
      const updatedTodos = { ...todos };
      for (const key in updatedTodos) {
        updatedTodos[key] = updatedTodos[key].map(t => 
          t.id === id ? { ...t, completed: !t.completed } : t
        );
      }
      setTodos(updatedTodos);
      localStorage.setItem('guest_todos', JSON.stringify(updatedTodos));
    }
  };

  const handleDeleteTodo = async (id: string) => {
    if (user && db) {
      await deleteDoc(doc(db, 'users', user.uid, 'todos', id));
    } else if (isGuest) {
      const updatedTodos = { ...todos };
      for (const key in updatedTodos) {
        updatedTodos[key] = updatedTodos[key].filter(t => t.id !== id);
        if (updatedTodos[key].length === 0) delete updatedTodos[key];
      }
      setTodos(updatedTodos);
      localStorage.setItem('guest_todos', JSON.stringify(updatedTodos));
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 text-slate-500">
        <div className="animate-pulse flex flex-col items-center">
          <div className="h-12 w-12 bg-slate-200 dark:bg-slate-800 rounded-full mb-4"></div>
          <div>Loading Event Horizon...</div>
        </div>
      </div>
    );
  }

  if (!user && !isGuest) {
    return (
      <>
        <div className="fixed top-4 right-4 z-50">
          <button
            onClick={() => setDarkMode(!darkMode)}
            className="p-3 rounded-full bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 shadow-md hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>
        <Login onGuestLogin={() => setIsGuest(true)} />
      </>
    );
  }

  const selectedDateKey = formatDateKey(selectedDate);
  const currentTodos = todos[selectedDateKey] || [];

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-7xl mx-auto space-y-6">
      <header className="flex justify-between items-center mb-8 animate-fade-in-down">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
            Event Horizon
            {isGuest && (
              <span className="px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 text-xs font-normal border border-slate-200 dark:border-slate-700 flex items-center gap-1">
                <WifiOff size={10} /> Guest
              </span>
            )}
          </h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm">
            {isGuest ? "Local session" : "Welcome back"}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setDarkMode(!darkMode)}
            className="p-2.5 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
            title="Toggle Theme"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
          <button
            onClick={handleSignOut}
            className="p-2.5 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 transition-colors"
            title="Sign Out"
          >
            <LogOut size={20} />
          </button>
        </div>
      </header>

      <main className="animate-fade-in space-y-6">
        <Countdown 
          event={event} 
          onEdit={() => setShowSettings(true)} 
        />

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-auto lg:h-[600px]">
          <div className="lg:col-span-7 h-[400px] lg:h-full">
            <Calendar 
              selectedDate={selectedDate} 
              onSelectDate={setSelectedDate}
              todos={todos}
              targetDateStr={event.date}
            />
          </div>
          <div className="lg:col-span-5 h-[500px] lg:h-full">
            <TodoList 
              date={selectedDate}
              todos={currentTodos}
              onAddTodo={handleAddTodo}
              onToggleTodo={handleToggleTodo}
              onDeleteTodo={handleDeleteTodo}
            />
          </div>
        </div>
      </main>

      {showSettings && (
        <EventSettings 
          currentEvent={event}
          onSave={handleUpdateEvent}
          onClose={() => setShowSettings(false)}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Layout, ArrowRight, User, AlertCircle, Loader2 } from 'lucide-react';
import { signInWithPopup } from 'firebase/auth';
import { auth, googleProvider } from '../lib/firebase';

interface LoginProps {
  onGuestLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onGuestLogin }) => {
  const [error, setError] = useState<string | null>(null);
  const [isDomainError, setIsDomainError] = useState(false);
  const [isRedirecting, setIsRedirecting] = useState(false);

  const handleGoogleLogin = async () => {
    setError(null);
    setIsDomainError(false);
    try {
      if (!auth || !googleProvider) throw new Error("Firebase not configured");
      await signInWithPopup(auth, googleProvider);
    } catch (err: any) {
      console.error(err);
      // Check for unauthorized domain error
      if (err?.code === 'auth/unauthorized-domain' || err?.message?.includes('unauthorized domain')) {
        setIsDomainError(true);
        setError("Preview domain detected. Switching to Guest Mode automatically...");
        setIsRedirecting(true);

        // Auto-redirect to guest mode after a brief delay so user sees what happened
        setTimeout(() => {
          onGuestLogin();
        }, 1500);
      } else {
        setError(err.message || "Failed to sign in.");
      }
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 px-4">
      <div className="max-w-md w-full bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-800 p-8 text-center animate-fade-in">

        <div className="flex justify-center mb-6">
          <div className="bg-indigo-600 p-3 rounded-xl text-white shadow-lg shadow-indigo-200 dark:shadow-none">
            <Layout size={32} />
          </div>
        </div>

        <h1 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
          Welcome to Event Horizon
        </h1>
        <p className="text-slate-500 dark:text-slate-400 mb-8">
          Sign in to sync your events and tasks across all your devices.
        </p>

        <button
          onClick={handleGoogleLogin}
          disabled={isRedirecting}
          className="w-full flex items-center justify-center gap-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-medium py-3 px-4 rounded-xl transition-all duration-200 group disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isRedirecting ? (
             <Loader2 size={20} className="animate-spin text-indigo-600" />
          ) : (
            <>
              <img src="https://www.google.com/favicon.ico" alt="Google" className="w-5 h-5" />
              <span>Sign in with Google</span>
              <ArrowRight size={16} className="text-slate-400 group-hover:translate-x-1 transition-transform" />
            </>
          )}
        </button>

        {error && (
          <div className={`mt-6 p-3 text-sm rounded-lg text-left flex items-start gap-2 ${isDomainError ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300' : 'bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400'}`}>
            <AlertCircle size={18} className="flex-shrink-0 mt-0.5" />
            <div>
              <span className="font-bold block mb-1">
                {isDomainError ? "Redirecting..." : "Error"}
              </span>
              {error}
            </div>
          </div>
        )}

        <div className="relative my-6">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-slate-200 dark:border-slate-700"></div>
          </div>
          <div className="relative flex justify-center text-xs uppercase">
            <span className="bg-white dark:bg-slate-900 px-2 text-slate-400">Or continue locally</span>
          </div>
        </div>

        <button
          onClick={onGuestLogin}
          disabled={isRedirecting}
          className={`
            w-full flex items-center justify-center gap-3 font-medium py-3 px-4 rounded-xl transition-all duration-200
            bg-indigo-50 dark:bg-slate-800 border border-indigo-100 dark:border-slate-700 hover:bg-indigo-100 dark:hover:bg-slate-700 text-indigo-700 dark:text-slate-300 disabled:opacity-50
          `}
        >
          <User size={20} className="text-indigo-600 dark:text-slate-400" />
          <span>Continue as Guest</span>
        </button>

        <div className="mt-8 text-xs text-slate-400 dark:text-slate-500">
          Guest data is stored in your browser's local storage.
        </div>
      </div>
    </div>
  );
};

export default Login;

